 <div class="toast" id="toast"></div>
 <div class="mobile" id="mobile"><div class="stickzone" id="stickzone"><div class="stick" id="stick"></div></div><div class="buttons"><button class="act" data-action="attack"><i>⚔</i>STRIKE</button><button class="act" data-action="grip"><i>✦</i>GRIP</button><button class="act" data-action="push"><i>◈</i>WAVE</button><button class="act" data-action="slam"><i>⌄</i>CRUSH</button></div></div>
 <div class="overlay" id="overlay"><div class="card"><div class="eyebrow" id="overEyebrow">A WARDEN RISES</div><h1 id="overTitle">THE<br>SHATTER</h1><p id="overText">무너진 성채를 되찾으려는 침략자들을 막아내세요.<br>붉은 칼날과 압도적인 힘으로 길을 여십시오.</p><button class="primary" id="startBtn">전투 시작</button><div class="keyguide"><span><b>A / D</b> 이동</span><span><b>SPACE</b> 참격</span><span><b>Q · E · R</b> 포스 기술</span></div></div></div>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false}),$=id=>document.getElementById(id);
+let W=0,H=0,dpr=1,ground=0,last=0,mode='menu',stage=0,kills=0,combo=0,comboTime=0,spawned=0,need=8,spawnClock=0,shake=0,slow=0,elapsed=0,toastTimer=0,soundOn=true,audio=null;
+const names=['THE SHATTER','ORBITAL VAULT','CINDER CITADEL'];
+const player={x:0,hp:100,max:100,face:1,attack:0,dash:0,invuln:0,energy:0,rage:0};
+let enemies=[],fx=[],objects=[],keys={},moveTouch=0,aircraft=null;
+function resize(){dpr=Math.min(devicePixelRatio||1,1.6);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ground=H*.77;player.x=Math.max(80,Math.min(W-80,player.x||W*.5))}
+addEventListener('resize',resize,{passive:true});resize();
+function rand(a,b){return a+Math.random()*(b-a)}
+function say(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=1.6}
+function audioTone(freq=90,dur=.1,type='sawtooth',gain=.035){if(!soundOn)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.value=gain;g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
+function setStage(n){stage=n;need=8+n*3;spawned=0;spawnClock=.7;enemies=[];aircraft=null;$('stageName').textContent=`0${n+1} · ${names[n]}`;$('status').innerHTML=`ELIMINATE THE INVADERS <span>· 0 / ${need}</span>`;say(['SECTOR 01 · THE SHATTER','SECTOR 02 · ORBITAL VAULT','SECTOR 03 · CINDER CITADEL'][n])}
+function begin(){mode='play';kills=0;combo=0;player.hp=player.max;player.energy=0;player.x=W*.5;fx=[];objects=[];setStage(0);$('overlay').classList.add('hide');last=performance.now();audioTone(120,.18,'triangle')}
+$('startBtn').onclick=()=>{if(mode==='menu'||mode==='lost')begin();else if(mode==='between')beginNext();else if(mode==='won')begin()};
+function beginNext(){if(stage<2){player.hp=Math.min(player.max,player.hp+30);setStage(stage+1);mode='play';$('overlay').classList.add('hide')}else finish(true)}
+$('soundBtn').onclick=()=>{$('soundBtn').textContent=`♫ SOUND: ${soundOn?'OFF':'ON'}`;soundOn=!soundOn;if(soundOn)audioTone(220,.08,'sine')};
+function overlay(eyebrow,title,text,button){$('overEyebrow').textContent=eyebrow;$('overTitle').innerHTML=title;$('overText').innerHTML=text;$('startBtn').textContent=button;$('overlay').classList.remove('hide')}
+function finish(win){mode=win?'won':'lost';if(win)overlay('THE CITADEL IS SILENT','VICTORY','세 구역의 침략군을 모두 격퇴했습니다.<br>황혼의 파수꾼은 다시 성문을 지킵니다.', '다시 플레이');else overlay('THE WARDEN HAS FALLEN','DEFEAT',`처치 ${kills} · 도달 구역 ${stage+1}<br>다시 일어나 전투를 이어가세요.`, '재도전')}
+function spawnEnemy(boss=false,plane=false){let side=Math.random()<.5?0:1;const e={x:side?W+35:-35,y:ground,hp:boss?150+stage*45:plane?65:30+stage*5,max:boss?150+stage*45:plane?65:30+stage*5,kind:boss?'boss':plane?'craft':Math.random()<.25?'drone':'raider',face:side?-1:1,attack:rand(.8,2),stun:0,air:0,flash:0,speed:boss?36:rand(34,58)+stage*4,dead:false};enemies.push(e);return e}
+function burst(x,y,color,n=12){for(let i=0;i<n;i++)fx.push({x,y,vx:rand(-190,190),vy:rand(-210,60),life:rand(.25,.65),max:.65,color,size:rand(1,4)})}
+function damage(e,amount,force=0){if(e.dead)return;e.hp-=amount;e.flash=.12;e.stun=Math.max(e.stun,force);if(e.hp<=0){e.dead=true;kills++;combo++;comboTime=2.2;player.energy=Math.min(100,player.energy+7+(e.kind==='boss'?22:0));burst(e.x,e.y-35,e.kind==='craft'?'#ff8b45':'#ff465b',e.kind==='craft'?35:13);audioTone(e.kind==='craft'?55:75,.12,'square',.025);shake=Math.max(shake,e.kind==='boss'||e.kind==='craft'?14:4);if(combo===5){player.energy=Math.min(100,player.energy+20);say('DOMINION · +20%');}else if(combo===10){say('UNSTOPPABLE');player.rage=5;}}}
+function attack(){if(mode!=='play'||player.attack>0)return;player.attack=.32;const reach=player.rage>0?145:105;let hit=false;for(const e of enemies){if(e.dead||Math.abs(e.x-player.x)>reach||Math.sign(e.x-player.x)!==player.face)continue;damage(e,player.rage>0?56:38,0.3);e.x+=player.face*44;hit=true}if(hit){player.energy=Math.min(100,player.energy+3);audioTone(170,.08,'sawtooth',.025)}else audioTone(140,.07,'sawtooth',.018);burst(player.x+player.face*55,ground-56,'#ff334d',7)}
+function grip(){if(mode!=='play'||player.energy<12)return;player.energy-=12;let target=enemies.filter(e=>!e.dead).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(!target||Math.abs(target.x-player.x)>W*.72){say('NO TARGET');return}target.air=.8;target.stun=1.25;target.x=player.x+player.face*120;target.y=ground-95;damage(target,35,1.1);burst(target.x,target.y,'#ff4259',15);audioTone(240,.18,'triangle');say(target.kind==='craft'?'CRAFT LIFTED':'FORCE GRIP')}
+function push(){if(mode!=='play'||player.energy<18)return;player.energy-=18;const reach=W*.43;for(const e of enemies){const dx=e.x-player.x;if(!e.dead&&Math.abs(dx)<reach&&Math.sign(dx)===player.face){damage(e,32,1.05);e.x+=player.face*Math.min(180,reach-Math.abs(dx)+35);e.air=.38}}burst(player.x+player.face*65,ground-65,'#ff5463',25);shake=9;audioTone(95,.25,'sawtooth');say('FORCE WAVE')}
+function slam(){if(mode!=='play'||player.energy<32)return;player.energy-=32;const radius=Math.min(W*.48,player.rage?330:255);for(const e of enemies){if(!e.dead&&Math.abs(e.x-player.x)<radius){damage(e,e.kind==='boss'?54:100,1.2);e.air=.7}}burst(player.x,ground-20,'#ff3d55',55);shake=18;slow=.18;audioTone(48,.45,'triangle',.08);say('DOMINION CRUSH')}
+function dash(){if(mode!=='play'||player.dash>0)return;player.dash=.5;player.invuln=.45;player.x=Math.max(48,Math.min(W-48,player.x+player.face*155));burst(player.x-player.face*30,ground-30,'#ed4b5c',8)}

