function update(dt){elapsed+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}if(mode!=='play')return;dt*=slow>0?.48:1;slow=Math.max(0,slow-dt);shake=Math.max(0,shake-dt*28);player.attack=Math.max(0,player.attack-dt);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);player.rage=Math.max(0,player.rage-dt);comboTime=Math.max(0,comboTime-dt);if(comboTime===0)combo=0;
let move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+stickX;if(move){player.x+=move*(player.rage?310:225)*dt;player.face=move>0?1:-1}player.x=Math.max(48,Math.min(W-48,player.x));
