if(spawned===need&&!enemies.some(e=>!e.dead)){spawned++;spawnEnemy(true);say('COMMANDER INBOUND')}
for(const e of enemies){if(e.dead)continue;e.flash=Math.max(0,e.flash-dt);e.stun=Math.max(0,e.stun-dt);e.air=Math.max(0,e.air-dt);e.attack-=dt;let dx=player.x-e.x,dist=Math.abs(dx);e.face=dx<0?-1:1;if(e.stun<=0&&e.air<=0){if(dist>(e.kind==='craft'?120:48))e.x+=Math.sign(dx)*e.speed*dt;if(dist<(e.kind==='boss'?100:58)&&e.attack<=0){e.attack=e.kind==='boss'?1.25:1.55;if(player.invuln<=0){let hurt=e.kind==='boss'?12:5;player.hp=Math.max(0,player.hp-hurt);player.invuln=.55;shake=5;burst(player.x,ground-45,'#e94d63',5);audioTone(62,.12,'square',.025);if(player.hp<=0)finish(false)}}}if(e.kind==='craft'&&e.air<=0)e.y=ground-5;else if(e.air>0)e.y=ground-65-Math.sin(e.air*7)*24;else e.y=ground-4}
enemies=enemies.filter(e=>!e.dead||e.flash>0);if(spawned>need&&!enemies.some(e=>!e.dead)){if(stage<2){mode='between';overlay('SECTOR SECURED',`ZONE 0${stage+1} CLEARED`,'침략군의 지휘관이 쓰러졌습니다.<br>체력을 회복하고 다음 구역으로 이동합니다.','다음 구역');}else finish(true)}
for(const p of fx){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=380*dt;p.life-=dt}fx=fx.filter(p=>p.life>0);player.energy=Math.max(0,player.energy-dt*.24);updateHUD()}
function updateHUD(){$('hpFill').style.width=`${100*player.hp/player.max}%`;$('hpText').textContent=`${Math.ceil(player.hp)} / ${player.max}`;$('forceFill').style.width=`${player.energy}%`;$('forceText').textContent=`${Math.floor(player.energy)}%`;$('kills').textContent=String(kills).padStart(2,'0');$('status').innerHTML=player.rage>0?`RAGE MODE <span>· ${player.rage.toFixed(1)}s</span>`:`ELIMINATE THE INVADERS <span>· ${Math.min(spawned,need)} / ${need}${spawned>need?' · COMMANDER':''}</span>`}

